package com.drivique.api.model;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="incident_responses",schema="support") public class IncidentResponse{@Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="incident_report_id",nullable=false) private IncidentReport incident;@ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="author_user_id",nullable=false) private User author;@Column(nullable=false,columnDefinition="text") private String message;@Column(name="attachment_url",length=500) private String attachmentUrl;@Column(name="created_at",nullable=false,updatable=false) private Instant createdAt=Instant.now();@Column(name="updated_at",nullable=false) private Instant updatedAt=Instant.now();protected IncidentResponse(){}public IncidentResponse(IncidentReport i,User a,String m,String url){incident=i;author=a;message=m;attachmentUrl=url;}}
